 proof fn lemma_push_preserves_no_dup<K>(s: Seq<K>, elem: K)
     requires
         s.no_duplicates(),
         !s.contains(elem),
     ensures
         s.push(elem).no_duplicates(),
 {
     broadcast use vstd::seq_lib::group_seq_properties;

     let pushed = s.push(elem);
     assert forall |i: int, j: int|
